/**
 * AWS credential chain, read-only, from environment variables and the shared credentials and config files:
 *   1. AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY / AWS_SESSION_TOKEN
 *   2. the profile (AWS_PROFILE, AWS_DEFAULT_PROFILE, else "default") in AWS_SHARED_CREDENTIALS_FILE
 *      (default ~/.aws/credentials), then in AWS_CONFIG_FILE (default ~/.aws/config)
 * Not supported: SSO, assume-role, credential_process and instance metadata (they need network or code execution).
 * Values are never logged or put in error messages; errors name only the variable, file or profile.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import type { AwsCredentials } from "./aws_sigv4.js";

export interface AwsEnvironment {
  env: Record<string, string | undefined>;
  /** Home directory for the default file locations (tests pass a temporary directory). */
  home?: string;
  readFile?: (file: string) => string | undefined;
}

export type IniFile = Record<string, Record<string, string>>;

/** INI with `[section]` headers, `key = value`, and `#` or `;` comment lines. Linear time; no regular expressions. */
export function parseIni(text: string, configFile = false): IniFile {
  const out: IniFile = {};
  let section: Record<string, string> | undefined;
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#") || line.startsWith(";")) continue;
    if (line.startsWith("[") && line.endsWith("]")) {
      let name = line.slice(1, -1).trim();
      if (configFile) {
        if (name.startsWith("profile ")) name = name.slice(8).trim();
        else if (name !== "default") { section = undefined; continue; }
      }
      section = out[name] ??= {};
      continue;
    }
    const eq = line.indexOf("=");
    if (eq < 0 || !section) continue;
    section[line.slice(0, eq).trim().toLowerCase()] = line.slice(eq + 1).trim();
  }
  return out;
}

function profileName(env: AwsEnvironment["env"]): string {
  return env.AWS_PROFILE?.trim() || env.AWS_DEFAULT_PROFILE?.trim() || "default";
}

function reader(e: AwsEnvironment): (file: string) => string | undefined {
  return e.readFile ?? ((file) => {
    try { return fs.readFileSync(file, "utf8"); } catch { return undefined; }
  });
}

function files(e: AwsEnvironment): { credentials: string; config: string } {
  const home = e.home ?? os.homedir();
  return {
    credentials: e.env.AWS_SHARED_CREDENTIALS_FILE?.trim() || path.join(home, ".aws", "credentials"),
    config: e.env.AWS_CONFIG_FILE?.trim() || path.join(home, ".aws", "config"),
  };
}

export class AwsCredentialError extends Error {}

export function resolveAwsCredentials(e: AwsEnvironment): AwsCredentials {
  const id = e.env.AWS_ACCESS_KEY_ID?.trim();
  const secret = e.env.AWS_SECRET_ACCESS_KEY?.trim();
  if (id && secret) return { accessKeyId: id, secretAccessKey: secret, ...(e.env.AWS_SESSION_TOKEN?.trim() ? { sessionToken: e.env.AWS_SESSION_TOKEN.trim() } : {}) };
  if (id || secret) throw new AwsCredentialError("AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must both be set");
  const profile = profileName(e.env);
  const read = reader(e);
  const f = files(e);
  const sources: Array<[string, boolean]> = [[f.credentials, false], [f.config, true]];
  for (const [file, isConfig] of sources) {
    const text = read(file);
    if (text === undefined) continue;
    const s = parseIni(text, isConfig)[profile];
    const keyId = s?.aws_access_key_id;
    const key = s?.aws_secret_access_key;
    if (keyId && key) return { accessKeyId: keyId, secretAccessKey: key, ...(s.aws_session_token ? { sessionToken: s.aws_session_token } : {}) };
  }
  throw new AwsCredentialError(`no AWS credentials: set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY, or add profile '${profile}' to ${f.credentials}`);
}

const REGION = /^[a-z]{2}(?:-[a-z]+)+-\d{1,2}$/;

/** AWS_REGION, AWS_DEFAULT_REGION, then `region` in the profile of the config file. */
export function resolveAwsRegion(e: AwsEnvironment): string | undefined {
  const fromEnv = e.env.AWS_REGION?.trim() || e.env.AWS_DEFAULT_REGION?.trim();
  if (fromEnv) return fromEnv;
  const text = reader(e)(files(e).config);
  const region = text === undefined ? undefined : parseIni(text, true)[profileName(e.env)]?.region;
  return region || undefined;
}

export function isAwsRegion(value: string): boolean {
  return REGION.test(value);
}
/**
 * AWS Signature Version 4 on node:crypto (no dependency). Signs one request and returns the headers to add.
 * Reference: https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_sigv-create-signed-request.html
 *
 * Only `host`, `content-type`, `x-amz-date` and `x-amz-security-token` are signed, so the caller may add other headers
 * (request ids, tracing) afterwards without invalidating the signature. The canonical path is the path as sent with
 * each segment encoded once more, which is the rule for every service except S3.
 */
import { createHash, createHmac } from "node:crypto";

export interface AwsCredentials {
  accessKeyId: string;
  secretAccessKey: string;
  sessionToken?: string;
}

export interface SigV4Input {
  method: string;
  url: string;
  /** Headers to sign besides host and x-amz-*; only content-type is used. */
  headers?: Record<string, string>;
  body: string | Uint8Array;
  region: string;
  service: string;
  credentials: AwsCredentials;
  now: Date;
}

const sha256Hex = (data: string | Uint8Array): string => createHash("sha256").update(data).digest("hex");
const hmac = (key: string | Buffer, data: string): Buffer => createHmac("sha256", key).update(data, "utf8").digest();

/** RFC 3986 unreserved characters stay; everything else is percent-encoded as UTF-8 with upper-case hex. */
export function uriEncode(value: string): string {
  return encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
}

/** `YYYYMMDD'T'HHMMSS'Z'` */
export function amzDate(now: Date): string {
  return now.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
}

export function signingKey(secret: string, dateStamp: string, region: string, service: string): Buffer {
  return hmac(hmac(hmac(hmac(`AWS4${secret}`, dateStamp), region), service), "aws4_request");
}

function canonicalQuery(params: URLSearchParams): string {
  const pairs = [...params.entries()].map(([k, v]) => [uriEncode(k), uriEncode(v)] as const);
  pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  return pairs.map(([k, v]) => `${k}=${v}`).join("&");
}

function canonicalPath(pathname: string): string {
  return pathname.split("/").map((seg) => (seg === "" ? "" : uriEncode(seg))).join("/") || "/";
}

export interface SigV4Result {
  /** Headers to send in addition to the caller's own (host is implied by the URL). */
  headers: Record<string, string>;
  canonicalRequest: string;
  stringToSign: string;
  signature: string;
}

export function signSigV4(input: SigV4Input): SigV4Result {
  const url = new URL(input.url);
  const date = amzDate(input.now);
  const dateStamp = date.slice(0, 8);
  const signed: Record<string, string> = { host: url.host, "x-amz-date": date };
  const contentType = Object.entries(input.headers ?? {}).find(([k]) => k.toLowerCase() === "content-type")?.[1];
  if (contentType !== undefined) signed["content-type"] = contentType.trim();
  if (input.credentials.sessionToken) signed["x-amz-security-token"] = input.credentials.sessionToken;
  const names = Object.keys(signed).sort();
  const canonicalHeaders = names.map((n) => `${n}:${signed[n].replace(/\s+/g, " ")}\n`).join("");
  const signedHeaders = names.join(";");
  const canonicalRequest = [
    input.method.toUpperCase(),
    canonicalPath(url.pathname),
    canonicalQuery(url.searchParams),
    canonicalHeaders,
    signedHeaders,
    sha256Hex(input.body),
  ].join("\n");
  const scope = `${dateStamp}/${input.region}/${input.service}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", date, scope, sha256Hex(canonicalRequest)].join("\n");
  const signature = createHmac("sha256", signingKey(input.credentials.secretAccessKey, dateStamp, input.region, input.service)).update(stringToSign, "utf8").digest("hex");
  const headers: Record<string, string> = {
    "X-Amz-Date": date,
    Authorization: `AWS4-HMAC-SHA256 Credential=${input.credentials.accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`,
  };
  if (input.credentials.sessionToken) headers["X-Amz-Security-Token"] = input.credentials.sessionToken;
  return { headers, canonicalRequest, stringToSign, signature };
}
/**
 * Validation for operator-declared provider settings (ids, base URLs, URL template variables, extra headers).
 * Pure functions: each returns the cleaned value or throws an Error naming the offending field.
 */
import { classifyDestination } from "./core/egress.js";

/** Lowercase letters, digits and hyphens, starting with a letter: safe inside `NEXUS_<ID>_BASE_URL` once mapped. */
const ID_GRAMMAR = /^[a-z][a-z0-9-]{0,31}$/;

/** Headers a provider definition may never set: routing, framing, or another party's credentials. */
const FORBIDDEN_HEADERS = new Set([
  "host", "content-length", "content-type", "transfer-encoding", "connection", "upgrade", "te", "trailer", "expect",
  "proxy-authorization", "proxy-connection", "cookie", "set-cookie", "forwarded", "x-forwarded-for", "x-forwarded-host",
  "x-forwarded-proto", "x-real-ip", "x-task-class",
]);

const AUTH_HEADERS = new Set(["authorization", "x-api-key", "x-goog-api-key", "api-key"]);
const HEADER_NAME = /^[A-Za-z0-9!#$%&'*+.^_`|~-]{1,64}$/;
/** Visible ASCII plus space and tab; no CR, LF or other control characters. */
const HEADER_VALUE = /^[\t\x20-\x7e]{0,512}$/;
const TEMPLATE_VARIABLE = /\{([^{}]*)\}/g;
const VARIABLE_VALUE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$/;

export function validateProviderId(id: unknown, field = "id"): string {
  if (typeof id !== "string" || !ID_GRAMMAR.test(id)) {
    throw new Error(`${field}: must be 1-32 characters of a-z, 0-9 and "-", starting with a letter`);
  }
  return id;
}

/**
 * A provider base URL: absolute, no userinfo, query or fragment surprises, and https unless the destination is local
 * (loopback, private, or listed in NEXUS_LOCAL_ORIGINS, as the egress classifier decides).
 */
export function validateBaseUrl(raw: unknown, field = "baseUrl", localOrigins: readonly string[] = []): string {
  if (typeof raw !== "string" || !raw.trim()) throw new Error(`${field}: a URL is required`);
  let url: URL;
  try {
    url = new URL(raw.trim());
  } catch {
    throw new Error(`${field}: not a valid absolute URL`);
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") throw new Error(`${field}: only http and https URLs are allowed`);
  if (url.username || url.password) throw new Error(`${field}: credentials in the URL are not allowed`);
  if (url.hash) throw new Error(`${field}: a URL fragment is not allowed`);
  if (url.protocol === "http:") {
    const boundary = classifyDestination(url.toString(), undefined, { localOrigins });
    if (boundary === "EXTERNAL_PUBLIC" || boundary === "EXTERNAL_BOUNDED") {
      throw new Error(`${field}: http is allowed only for local destinations; use https or add the origin to NEXUS_LOCAL_ORIGINS`);
    }
  }
  return url.toString().replace(/\/+$/, "");
}

/**
 * Fill `{name}` variables in a URL template. Each value is validated before substitution so it cannot change the
 * host, path structure or query; an unknown or unfilled variable is an error.
 */
export function expandUrlTemplate(template: string, values: Readonly<Record<string, string | undefined>>, field = "baseUrl"): string {
  return template.replace(TEMPLATE_VARIABLE, (_m, name: string) => {
    const value = values[name];
    if (value === undefined) throw new Error(`${field}: variable {${name}} has no value`);
    if (!VARIABLE_VALUE.test(value)) throw new Error(`${field}: value of {${name}} must be letters, digits, ".", "_" or "-"`);
    return value;
  });
}

/** Extra headers a provider sends on every request; auth belongs to the auth style, never here. */
export function validateExtraHeaders(headers: unknown, field = "headers"): Record<string, string> {
  if (headers === undefined) return {};
  if (!headers || typeof headers !== "object" || Array.isArray(headers)) throw new Error(`${field}: must be an object of header names to values`);
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(headers)) {
    if (!HEADER_NAME.test(name)) throw new Error(`${field}.${name}: not a valid header name`);
    const lower = name.toLowerCase();
    if (FORBIDDEN_HEADERS.has(lower)) throw new Error(`${field}.${name}: this header cannot be set by a provider`);
    if (AUTH_HEADERS.has(lower)) throw new Error(`${field}.${name}: credentials are set by the provider's auth style, not as a static header`);
    if (typeof value !== "string" || !HEADER_VALUE.test(value)) throw new Error(`${field}.${name}: value must be printable text without line breaks`);
    out[name] = value;
  }
  return out;
}

/** The header that carries a provider's key: any valid name except routing/framing headers and the two built-in styles. */
export function validateAuthHeaderName(name: unknown, field = "authHeader"): string {
  if (typeof name !== "string" || !HEADER_NAME.test(name)) throw new Error(`${field}: not a valid header name`);
  const lower = name.toLowerCase();
  if (lower === "authorization" || lower === "x-api-key") throw new Error(`${field}: use auth "bearer" or "x-api-key" for ${name}`);
  if (FORBIDDEN_HEADERS.has(lower)) throw new Error(`${field}: this header cannot be set by a provider`);
  return name;
}

/** Header names an operator-declared provider adds, for the redaction list (keys never reach logs). */
export function redactableHeaderNames(authHeader: string | undefined, extra: Readonly<Record<string, string>>): string[] {
  return [...new Set([...(authHeader ? [authHeader.toLowerCase()] : []), ...Object.keys(extra).map((n) => n.toLowerCase())])];
}
/**
 * The operator's own provider declarations: `~/.config/nexus/providers.json`. Read only from the operator's home (a
 * project file is never consulted); every field is validated and errors name the field that is wrong.
 *
 *   { "providers": { "azure-openai": {
 *       "label": "Azure OpenAI", "protocol": "openai-chat",
 *       "baseUrl": "https://{resource}.openai.azure.com/openai/deployments/{deployment}",
 *       "variables": { "resource": "acme", "deployment": "gpt-4o" },
 *       "query": { "api-version": "2024-10-21" },
 *       "auth": "header", "authHeader": "api-key", "credentialEnv": "AZURE_OPENAI_API_KEY" } } }
 */
import fs from "node:fs";
import type { AuthStyle, ProviderDefinition, WireProtocol } from "./providers.js";
import { expandUrlTemplate, validateAuthHeaderName, validateBaseUrl, validateExtraHeaders, validateProviderId } from "./provider_safety.js";

const PROTOCOLS: readonly WireProtocol[] = ["openai-chat", "openai-responses", "anthropic-messages", "gemini-generate-content", "bedrock-converse"];
const AUTHS: readonly AuthStyle[] = ["bearer", "x-api-key", "header", "none", "sigv4"];
const USAGES = ["openrouter", "stream-options", "native"] as const;
const ENV_NAME = /^[A-Z][A-Z0-9_]{0,63}$/;
const QUERY_NAME = /^[A-Za-z0-9_.-]{1,64}$/;
const QUERY_VALUE = /^[A-Za-z0-9_.:-]{1,64}$/;
const KNOWN_FIELDS = new Set([
  "label", "protocol", "baseUrl", "variables", "query", "headers", "auth", "authHeader", "credentialEnv", "streamOnly", "omitParams", "usage",
]);

const isObject = (v: unknown): v is Record<string, unknown> => Boolean(v) && typeof v === "object" && !Array.isArray(v);

function oneOf<T extends string>(value: unknown, allowed: readonly T[], field: string): T {
  if (typeof value !== "string" || !allowed.includes(value as T)) throw new Error(`${field}: must be one of ${allowed.join(", ")}`);
  return value as T;
}

function parseProvider(id: string, raw: unknown, localOrigins: readonly string[]): ProviderDefinition {
  const f = `providers.${id}`;
  if (!isObject(raw)) throw new Error(`${f}: must be an object`);
  for (const key of Object.keys(raw)) if (!KNOWN_FIELDS.has(key)) throw new Error(`${f}.${key}: unknown field`);
  const label = typeof raw.label === "string" && raw.label.trim() && raw.label.length <= 80 ? raw.label.trim() : undefined;
  if (!label) throw new Error(`${f}.label: a short label is required`);
  const protocol = oneOf(raw.protocol ?? "openai-chat", PROTOCOLS, `${f}.protocol`);
  const auth = oneOf(raw.auth ?? "bearer", AUTHS, `${f}.auth`);

  let variables: Record<string, string> = {};
  if (raw.variables !== undefined) {
    if (!isObject(raw.variables)) throw new Error(`${f}.variables: must be an object`);
    variables = Object.fromEntries(Object.entries(raw.variables).map(([k, v]) => [k, typeof v === "string" ? v : ""]));
  }
  // Omitted: the operator supplies the URL (NEXUS_<ID>_BASE_URL or --base-url), as for the generic `compatible` provider.
  if (raw.baseUrl !== undefined && typeof raw.baseUrl !== "string") throw new Error(`${f}.baseUrl: must be a URL string`);
  const baseUrl = raw.baseUrl === undefined ? undefined : validateBaseUrl(expandUrlTemplate(raw.baseUrl, variables, `${f}.baseUrl`), `${f}.baseUrl`, localOrigins);

  let authHeader: string | undefined;
  if (auth === "header") {
    if (raw.authHeader === undefined) throw new Error(`${f}.authHeader: required when auth is "header"`);
    authHeader = validateAuthHeaderName(raw.authHeader, `${f}.authHeader`);
  } else if (raw.authHeader !== undefined) {
    throw new Error(`${f}.authHeader: only valid when auth is "header"`);
  }

  let credentialEnv: string | undefined;
  if (raw.credentialEnv !== undefined) {
    if (typeof raw.credentialEnv !== "string" || !ENV_NAME.test(raw.credentialEnv)) throw new Error(`${f}.credentialEnv: must be an environment variable name (A-Z, 0-9, _)`);
    credentialEnv = raw.credentialEnv;
  } else if (auth !== "none" && auth !== "sigv4") {
    throw new Error(`${f}.credentialEnv: required unless auth is "none" or "sigv4"`);
  }

  let query: Record<string, string> | undefined;
  if (raw.query !== undefined) {
    if (!isObject(raw.query)) throw new Error(`${f}.query: must be an object`);
    query = {};
    for (const [k, v] of Object.entries(raw.query)) {
      if (!QUERY_NAME.test(k)) throw new Error(`${f}.query.${k}: not a valid parameter name`);
      if (typeof v !== "string" || !QUERY_VALUE.test(v)) throw new Error(`${f}.query.${k}: value must be letters, digits or . _ : -`);
      query[k] = v;
    }
  }

  let omitParams: string[] | undefined;
  if (raw.omitParams !== undefined) {
    if (!Array.isArray(raw.omitParams) || !raw.omitParams.every((p) => typeof p === "string" && /^[a-z_]{1,48}$/.test(p))) throw new Error(`${f}.omitParams: must be a list of parameter names`);
    omitParams = raw.omitParams as string[];
  }
  if (raw.streamOnly !== undefined && typeof raw.streamOnly !== "boolean") throw new Error(`${f}.streamOnly: must be true or false`);

  const headers = validateExtraHeaders(raw.headers, `${f}.headers`);
  return {
    id: validateProviderId(id, `${f} (id)`),
    label,
    protocol,
    ...(baseUrl ? { baseUrl } : {}),
    ...(credentialEnv ? { credentialEnv } : {}),
    auth,
    ...(authHeader ? { authHeader } : {}),
    ...(Object.keys(headers).length ? { staticHeaders: headers } : {}),
    ...(query && Object.keys(query).length ? { query } : {}),
    ...(raw.streamOnly ? { streamOnly: true } : {}),
    ...(omitParams?.length ? { omitParams } : {}),
    usage: raw.usage === undefined ? (protocol === "openai-chat" ? "stream-options" : "native") : oneOf(raw.usage, USAGES, `${f}.usage`),
    methods: auth === "none" ? [] : [{ id: "api-key", label: "API key", kind: "key" }],
  };
}

export function parseProvidersDocument(raw: unknown, localOrigins: readonly string[] = []): ProviderDefinition[] {
  if (!isObject(raw)) throw new Error("providers.json: must be an object with a \"providers\" map");
  for (const key of Object.keys(raw)) if (key !== "providers") throw new Error(`providers.json: unknown field "${key}"`);
  if (!isObject(raw.providers)) throw new Error("providers: must be an object mapping provider ids to definitions");
  return Object.entries(raw.providers).map(([id, def]) => parseProvider(id, def, localOrigins));
}

/** Read the operator's providers file; a missing file declares none. */
export function readProvidersFile(file: string, localOrigins: readonly string[] = []): ProviderDefinition[] {
  let text: string;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw new Error(`providers.json: cannot read ${file}: ${(error as Error).message}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new Error(`providers.json: ${file} is not valid JSON`);
  }
  return parseProvidersDocument(parsed, localOrigins);
}

